// ─────────────────────────────────────────────
// The record collection = a public Spotify playlist.
//
// src/data/playlist.json is generated by `npm run playlist` (see scripts/fetch-playlist.mjs).
// Change PLAYLIST_ID there — or swap the playlist link — and re-run it to refresh everything.
//
// Nothing here is invented: titles, artists and album art all come from Spotify, and the
// audio is played by Spotify's own embedded player rather than copied into this site.
// ─────────────────────────────────────────────
import data from './playlist.json';

export type Track = {
  id: string;
  uri: string;
  title: string;
  artist: string;
  duration: number | null;
  cover: string | null;
};

export const playlist = data as {
  id: string;
  name: string;
  url: string;
  cover: string | null;
  fetched: string;
  tracks: Track[];
};

/** How many sleeves sit in the pile at once. The rest of the playlist is a next/shuffle away. */
export const CRATE = 9;

// Sleeve tints, picked from the site's palette. Stable per track, so a record always
// comes back wearing the same colour.
const TINTS: { paper: string; label: string }[] = [
  { paper: '#e8e4f3', label: '#b9a6fb' },
  { paper: '#f7e2cf', label: '#ff8a63' },
  { paper: '#dfe9e2', label: '#63d3a0' },
  { paper: '#fdeedd', label: '#ffd84a' },
  { paper: '#f4e0e8', label: '#ff7eb3' },
  { paper: '#dfe6f6', label: '#86b4f7' },
];

export function tintFor(id: string) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return TINTS[h % TINTS.length];
}

/** The handwritten line in the corner of the room. */
export const roomNote = 'things I listen to when my brain gets too loud.';
export const deckLabel = 'currently on repeat';
